-- Keep one shared guide per mode. Existing rows of these titles are updated in place.
alter table public.guides add column if not exists author_name text;
alter table public.guides alter column author_id drop not null;
do $$
declare
  tank_text text := $tank$<h2>1. Use cover</h2><p>Avoid crossing open ground while enemies can see you. Use buildings, terrain, and obstacles to break line of sight.</p><h2>2. Protect your vehicle</h2><p>Use ridges and solid cover to expose as little of your tank as possible while aiming. The best position depends on your vehicle.</p><h2>3. Move after firing</h2><p>After a shot, move behind cover and change position when it is safe. Repeated shots from one exposed position make you easier to target.</p><h2>4. Choose fights carefully</h2><p>Check nearby routes, keep an escape path, and use your team's positions to avoid being surrounded.</p><h2>5. Help win the objective</h2><p>Capture or defend objectives when safe instead of chasing distant opponents.<p> <strong>Practice tip:</strong> Focus on surviving after each shot and reaching useful positions before engaging.</p></p>$tank$;
  air_text text := $air$<h2>1. Protect your energy</h2><p>Speed and altitude give a fighter options. Avoid turning tightly for too long when it costs speed, and climb when there is room to build an advantage.</p><h2>2. Check your surroundings</h2><p>Scan for other aircraft and note where teammates are before committing to a target.</p><h2>3. Make one controlled attack</h2><p>Approach with an exit path in mind, aim ahead of a moving aircraft, fire a short burst, then extend away.</p><h2>4. Work with your team</h2><p>Stay close enough to support friendly aircraft instead of chasing a distant target alone.</p><h2>5. Return to the objective</h2><p>Reassess after an attack, regain speed or altitude when safe, then help defend or reach the objective.</p>$air$;
  sea_text text := $sea$<h2>1. Control your distance</h2><p>Use your ship's range and weapon strengths to choose when to engage. Avoid sailing directly into an enemy's effective firing zone.</p><h2>2. Angle your armor</h2><p>Turn your ship so incoming fire meets more belt armor while keeping your guns trained on the target.</p><h2>3. Watch the horizon</h2><p>Track enemy movement, islands, and likely torpedo lanes. Cover can hide threats as well as protect you.</p><h2>4. Keep changing course</h2><p>Steady movement makes your ship easier to hit. Change course carefully and watch for incoming torpedoes.</p><h2>5. Fight for the objective</h2><p>Protect capture zones and support nearby allies. <p><strong>Practice tip:</strong> Focus on positioning and course changes before firing.</p></p>$sea$;
begin
  update public.guides set content=tank_text, author_id=null, author_name=null where lower(title)=lower('Tank Combat Basics');
  if not found then insert into public.guides(title,content,author_id,author_name) values('Tank Combat Basics',tank_text,null,null); end if;
  update public.guides set content=air_text, author_id=null, author_name='Simon Riley' where lower(title)=lower('Aviation Combat Basics');
  if not found then insert into public.guides(title,content,author_id,author_name) values('Aviation Combat Basics',air_text,null,'Simon Riley'); end if;
  update public.guides set content=sea_text, author_id=null, author_name='Jimbei' where lower(title)=lower('Naval Combat Basics');
  if not found then insert into public.guides(title,content,author_id,author_name) values('Naval Combat Basics',sea_text,null,'Jimbei'); end if;
end $$;
